using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
namespace CampaignDemo {
 [DisallowMultipleComponent,DefaultExecutionOrder(-120)]
 public sealed class TacticalTargetOrders:MonoBehaviour {
  public BattleWorld world;ArmySelection selection;UnitContextOrders context;CampaignHUD hud;
  sealed class Chase {public bool straight;public BattleUnit actor,target;public uint revision;public float next;public Vector3 destination;}
  sealed class FortChase {public bool straight;public BattleUnit actor;public Fortification fort;public uint revision;public float next;}
  readonly List<FortChase> fortChasing=new List<FortChase>();public Fortification FortTarget {get{return fortChasing.Count==0?null:fortChasing[fortChasing.Count-1].fort;}}
  readonly List<Chase> chasing=new List<Chase>();LineRenderer frame;Material material;
  public BattleUnit Target {get;private set;}public int PendingCount {get{return chasing.Count+fortChasing.Count;}}
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){SceneManager.sceneLoaded-=Loaded;SceneManager.sceneLoaded+=Loaded;}
  static void Loaded(Scene scene,LoadSceneMode mode){foreach(var w in Object.FindObjectsOfType<BattleWorld>())if(w.gameObject.scene==scene&&LocalTacticalBattle.EnabledFor(w)&&w.GetComponent<TacticalTargetOrders>()==null)w.gameObject.AddComponent<TacticalTargetOrders>().world=w;}
  void Resolve(){if(world==null)world=GetComponent<BattleWorld>();if(selection==null)selection=GetComponent<ArmySelection>();if(context==null)context=GetComponent<UnitContextOrders>();if(hud==null)hud=FindObjectOfType<CampaignHUD>();}
  bool Available {get{return world!=null&&world.Initialized&&!world.SimulationEnded&&LocalTacticalBattle.EnabledFor(world)&&(NetworkTacticalOrders.Executing||world.setup.modes.CurrentMode==MouseCommandMode.RoadMarch||world.setup.modes.CurrentMode==MouseCommandMode.FreeMarch);}}
  bool OverUI(){return LocalMapSettings.CapturesPointer(world)||EventSystem.current!=null&&(EventSystem.current.IsPointerOverGameObject()||EventSystem.current.currentSelectedGameObject!=null&&EventSystem.current.currentSelectedGameObject.GetComponent<UnityEngine.UI.InputField>()!=null);}
  void Update(){Resolve();if(!Available){if(LocalPvpSession.Active==null)CancelAll(true);else if(LocalPvpSession.Simulate){TickPursuits();TickFortPursuits();}return;}if(!UnitContextOrders.Consumed&&(Input.GetKeyDown(KeyCode.T)||Input.GetKeyDown(KeyCode.Escape)||Input.GetMouseButtonDown(1)))CancelAll(true);if(LocalPvpSession.Simulate){TickPursuits();TickFortPursuits();}if(context==null||hud==null||hud.ActiveTool!=CampaignHUD.Tool.None||UnitContextOrders.Consumed||!Input.GetMouseButtonDown(0)||OverUI())return;if(TryClick(Input.mousePosition))UnitContextOrders.ConsumePointer();else if(!FriendlyUnderPointer(Input.mousePosition))CancelSelected(false);}
  bool FriendlyUnderPointer(Vector2 screen){foreach(var u in world.units){if(u==null||!u.OnMap||u.ownerId!=world.currentPlayer)continue;var p=world.setup.mapCamera.WorldToScreenPoint(u.transform.position);if(p.z>0&&Vector2.Distance(screen,p)<world.setup.settings.selectionPixels)return true;}return false;}
  public bool TryClick(Vector2 screen){Resolve();if(!Available||selection==null||selection.Selected==null)return false;var selectedActor=selection.Selected.GetComponent<BattleUnit>();if(TryFortClick(selectedActor,screen))return true;BattleUnit hit=null;float distance=world.setup.settings.selectionPixels;foreach(var u in world.units){if(u==null||!u.OnMap||!world.IsVisible(world.currentPlayer,u))continue;var at=world.setup.mapCamera.WorldToScreenPoint(u.transform.position);float d=Vector2.Distance(screen,at);if(at.z>0&&d<distance){distance=d;hit=u;}}if(hit==null||selection.Contains(hit.GetComponent<ArmyRoadMover>()))return false;
   var actor=selection.Selected.GetComponent<BattleUnit>();if(hit.ownerId!=world.currentPlayer){QueuePursuit(actor,hit);return true;}
   var carrier=hit.GetComponent<PersonnelCarrier>();if(carrier!=null){CancelSelected(false);context.SelectCarrierOnClick(actor,carrier);return true;}
   if(hit.GetComponent<TransportTruck>()!=null){hud.SelectUnit(hit);return true;}return false;
  }
  public bool QueuePursuit(BattleUnit actor,BattleUnit target){Resolve();if(NetworkTacticalOrders.Forward(world,actor,"pursuit",out var forwarded,target:target))return forwarded;if(!Available||actor==null||!actor.OnMap||actor.ownerId!=NetworkTacticalOrders.Player(world,actor.ownerId)||target==null||!target.OnMap||target.ownerId==actor.ownerId||!world.IsVisible(actor.ownerId,target)){context?.RejectMovement("目标不可见或无法追踪");return false;}
   CancelFortFor(actor,false);context?.CancelEntries(false);chasing.RemoveAll(x=>x.actor==actor);var chase=new Chase{straight=NetworkTacticalOrders.Straight(world),actor=actor,target=target,revision=actor.Motor.ArrowOrderRevision};chasing.Add(chase);Target=target;
   if(!Advance(chase)){chasing.Remove(chase);if(chasing.Count==0)Target=null;return false;}hud?.SetCommandFeedback("已锁定可见敌军，正在追踪；进入射程后按原有规则交火");return true;
  }
  bool Advance(Chase order){var actor=order.actor;var target=order.target;float range=Mathf.Max(.05f,UnitRanges.Attack(actor));float distance=Vector2.Distance(actor.transform.position,target.transform.position);order.next=Time.time+.7f;
   if(distance<=range*.94f){if(actor.Motor.IsMoving)actor.Motor.Stop();order.revision=actor.Motor.ArrowOrderRevision;return true;}
   if(!actor.CanMove){context?.RejectMovement("部队当前不能追踪移动");return false;}
   var delta=(target.transform.position-actor.transform.position).normalized;var goal=target.transform.position-delta*(range*.8f);var map=world.setup.freeMarchMap;var free=actor.GetComponent<ArmyFreeMarchMover>();List<RoadPoint> route;
   if(order.straight){route=new List<RoadPoint>{new RoadPoint(actor.transform.position.x,actor.transform.position.y),new RoadPoint(goal.x,goal.y)};if(!free.CanTraverse(map,route[0],route[1])){context?.RejectMovement("直线追踪被地形阻挡，请用 Q 自动寻路");return false;}}
   else route=LocalRoadAStar.Plan(map,free.AllowedTerrain,actor.transform.position,goal,distance>12?.4f:.2f,30000);
   if(route==null){context?.RejectMovement("无法到达敌军附近");return false;}var result=world.GetComponent<BattleCommandService>().Submit(new BattleCommand{kind=BattleCommandKind.FreeRoute,playerId=actor.ownerId,unitId=actor.unitId,route=route});if(!result.accepted&&!result.pending){context?.RejectMovement(result.reason);return false;}order.destination=target.transform.position;order.revision=actor.Motor.ArrowOrderRevision;return true;
  }
  public void TickPursuits(){Resolve();if(!NetworkTacticalOrders.Authority)return;for(int i=chasing.Count-1;i>=0;i--){var c=chasing[i];if(c.actor==null||!c.actor.OnMap||c.actor.ownerId!=NetworkTacticalOrders.Player(world,c.actor.ownerId)||c.target==null||!c.target.OnMap||c.target.ownerId==c.actor.ownerId||!world.IsVisible(c.actor.ownerId,c.target)){if(c.actor!=null&&c.actor.Motor.ArrowOrderRevision==c.revision)c.actor.Motor.Stop();chasing.RemoveAt(i);continue;}
    if(c.actor.Motor.ArrowOrderRevision!=c.revision){chasing.RemoveAt(i);continue;}float range=UnitRanges.Attack(c.actor);if(Vector2.Distance(c.actor.transform.position,c.target.transform.position)<=range*.94f){if(c.actor.Motor.IsMoving)c.actor.Motor.Stop();continue;}if(Time.time<c.next)continue;if(c.actor.Motor.IsMoving&&Vector2.Distance(c.destination,c.target.transform.position)<.25f)continue;if(!Advance(c))chasing.RemoveAt(i);
   }Target=chasing.Count==0?null:chasing[chasing.Count-1].target;
  }
  bool TryFortClick(BattleUnit actor,Vector2 screen){if(actor==null||actor.combatDefinition.role!=UnitRole.Engineer)return false;var camera=world.setup.mapCamera;var p=MapProjection.Ground(camera,new Vector2(screen.x,screen.y));p.z=0;float limit=world.setup.settings.selectionPixels*2*camera.orthographicSize/Mathf.Max(1,camera.pixelHeight);Fortification hit=null;var combined=world.GetComponent<CombinedArmsWorld>();if(combined==null)return false;foreach(var f in combined.fortifications)if(f!=null&&!f.Destroyed&&f.VisibleTo(world,actor.ownerId)){float distance=f.DistanceTo(p);if(distance<limit){limit=distance;hit=f;}}if(hit==null)return false;QueueFortPursuit(actor,hit);return true;}
  public bool QueueFortPursuit(BattleUnit actor,Fortification fort){Resolve();if(NetworkTacticalOrders.Forward(world,actor,"fort",out var forwarded,fort:fort))return forwarded;if(!Available||actor==null||!actor.OnMap||actor.ownerId!=NetworkTacticalOrders.Player(world,actor.ownerId)||actor.combatDefinition.role!=UnitRole.Engineer||fort==null||fort.Destroyed||!fort.VisibleTo(world,actor.ownerId)){context?.RejectMovement("只有工兵可以锁定可见的防线");return false;}CancelFor(actor,false);context?.CancelEntriesFor(actor,false);var result=world.GetComponent<BattleCommandService>().Submit(new BattleCommand{kind=BattleCommandKind.AttackFortification,playerId=actor.ownerId,unitId=actor.unitId,destination=fort.ClosestPoint(actor.transform.position),enabled=true});if(!result.accepted){context?.RejectMovement(result.reason);return false;}var order=new FortChase{straight=NetworkTacticalOrders.Straight(world),actor=actor,fort=fort,revision=actor.Motor.ArrowOrderRevision};if(!AdvanceFort(order)){ClearFort(order,false);return false;}fortChasing.Add(order);hud?.SetCommandFeedback("工兵已锁定防线，接近后优先攻击或拆除");return true;}
  bool AdvanceFort(FortChase order){var actor=order.actor;order.next=Time.time+.7f;if(order.fort.DistanceTo(actor.transform.position)<=UnitRanges.Attack(actor)*.94f){actor.Motor.Stop();order.revision=actor.Motor.ArrowOrderRevision;actor.GetComponent<CampaignUnit>().fortTarget=order.fort;return true;}if(!actor.CanMove)return false;var target=order.fort.ClosestPoint(actor.transform.position);var direction=(target-actor.transform.position).normalized;var goal=target-direction*(UnitRanges.Attack(actor)*.8f);var free=actor.GetComponent<ArmyFreeMarchMover>();var map=world.setup.freeMarchMap;List<RoadPoint> route;if(order.straight){route=new List<RoadPoint>{new RoadPoint(actor.transform.position.x,actor.transform.position.y),new RoadPoint(goal.x,goal.y)};if(!free.CanTraverse(map,route[0],route[1])){context?.RejectMovement("直线接近防线被地形阻挡，请用1寻路");return false;}}else route=LocalRoadAStar.Plan(map,free.AllowedTerrain,actor.transform.position,goal,.2f,30000);if(route==null){context?.RejectMovement("无法接近防线");return false;}var result=world.GetComponent<BattleCommandService>().Submit(new BattleCommand{kind=BattleCommandKind.FreeRoute,playerId=actor.ownerId,unitId=actor.unitId,route=route});if(!result.accepted)return false;actor.GetComponent<CampaignUnit>().fortTarget=order.fort;order.revision=actor.Motor.ArrowOrderRevision;return true;}
  void ClearFort(FortChase order,bool stop){if(order.actor==null)return;var state=order.actor.GetComponent<CampaignUnit>();if(state!=null&&state.fortTarget==order.fort)state.fortTarget=null;if(stop&&order.actor.Motor.ArrowOrderRevision==order.revision)order.actor.Motor.Stop();}
  void CancelFortFor(BattleUnit actor,bool stop){for(int i=fortChasing.Count-1;i>=0;i--)if(fortChasing[i].actor==actor){ClearFort(fortChasing[i],stop);fortChasing.RemoveAt(i);}}
  public void TickFortPursuits(){Resolve();if(!NetworkTacticalOrders.Authority)return;for(int i=fortChasing.Count-1;i>=0;i--){var c=fortChasing[i];if(c.actor==null||!c.actor.OnMap||c.actor.ownerId!=NetworkTacticalOrders.Player(world,c.actor.ownerId)||c.fort==null||c.fort.Destroyed||!c.fort.VisibleTo(world,c.actor.ownerId)||c.actor.GetComponent<CampaignUnit>().fortTarget!=c.fort||c.actor.Motor.ArrowOrderRevision!=c.revision){ClearFort(c,true);fortChasing.RemoveAt(i);continue;}if(c.fort.DistanceTo(c.actor.transform.position)<=UnitRanges.Attack(c.actor)*.94f){if(c.actor.Motor.IsMoving)c.actor.Motor.Stop();c.revision=c.actor.Motor.ArrowOrderRevision;continue;}if(Time.time<c.next||c.actor.Motor.IsMoving)continue;if(!AdvanceFort(c)){ClearFort(c,true);fortChasing.RemoveAt(i);}}}
  void CancelSelected(bool stop){if(selection==null)return;foreach(var army in selection.SelectedArmies)CancelFortFor(army.GetComponent<BattleUnit>(),stop);for(int i=chasing.Count-1;i>=0;i--)if(selection.Contains(chasing[i].actor.GetComponent<ArmyRoadMover>())){if(stop)chasing[i].actor.Motor.Stop();chasing.RemoveAt(i);}if(chasing.Count==0)Target=null;}
  public void CancelFor(BattleUnit actor,bool stop){CancelFortFor(actor,stop);for(int i=chasing.Count-1;i>=0;i--)if(chasing[i].actor==actor){if(stop&&actor!=null&&actor.Motor.ArrowOrderRevision==chasing[i].revision)actor.Motor.Stop();chasing.RemoveAt(i);}Target=chasing.Count==0?null:chasing[chasing.Count-1].target;}
  public void CancelAll(bool stop){foreach(var c in fortChasing)ClearFort(c,stop);fortChasing.Clear();foreach(var c in chasing)if(stop&&c.actor!=null&&c.actor.Motor.ArrowOrderRevision==c.revision)c.actor.Motor.Stop();chasing.Clear();Target=null;}
  void LateUpdate(){if(world==null||(FortTarget==null&&(Target==null||!world.IsVisible(world.currentPlayer,Target)))){if(frame!=null)frame.enabled=false;return;}if(frame==null){var go=new GameObject("敌军追踪目标 · 红框");go.transform.SetParent(transform,false);frame=go.AddComponent<LineRenderer>();material=new Material(Shader.Find("Sprites/Default"));frame.sharedMaterial=material;frame.loop=true;frame.positionCount=4;frame.sortingOrder=36;frame.startColor=frame.endColor=new Color(.95f,.12f,.12f);}
   var camera=world.setup.mapCamera;float pixel=2*camera.orthographicSize/Mathf.Max(1,camera.pixelHeight),half=pixel*25;var p=FortTarget!=null?FortTarget.ClosestPoint(fortChasing[fortChasing.Count-1].actor.transform.position):Target.transform.position;frame.startWidth=frame.endWidth=pixel*1.5f;frame.enabled=true;frame.SetPositions(new[]{p+new Vector3(-half,-half),p+new Vector3(-half,half),p+new Vector3(half,half),p+new Vector3(half,-half)});
  }
  void OnDisable(){CancelAll(false);if(frame!=null)frame.enabled=false;}
  void OnDestroy(){CancelAll(false);if(frame!=null)Destroy(frame.gameObject);if(material!=null)Destroy(material);}
 }
}

